  5882  /*
  5883    Load files (whose name is <categoryid>_<label>.<extension>) stored
  5884    in a directory and bind each domain to the specified category.
  5885
  5886    It can be used to load all files store in the lists/ directory
  5887
  5888    It returns the number of loaded files or -1 in case of failure
  5889  */
  5890  int ndpi_load_categories_dir(struct ndpi_detection_module_struct *ndpi_str,
  5891                               char *dir_path) {
  5892    DIR *dirp;
  5893    struct dirent *dp;
  5894    int failed_files = 0;
  5895    int num_loaded = 0;
  5896
  5897    if(!ndpi_str || !dir_path)
  5898      return(0);
  5899
  5900    dirp = opendir(dir_path);
  5901    if (dirp == NULL)
  5902      return(0);
  5903
  5904    while((dp = readdir(dirp)) != NULL) {
  5905      char *underscore, *extn;
  5906
  5907      if(dp->d_name[0] == '.') continue;
  5908      extn = strrchr(dp->d_name, '.');
  5909
  5910      if((extn == NULL) || strcmp(extn, ".list"))
  5911        continue;
  5912
  5913      /* Check if the format is <proto it>_<string>.<extension> */
  5914      if((underscore = strchr(dp->d_name, '_')) != NULL) {
  5915        int cat_id;
  5916        const char *errstrp;
  5917
  5918        underscore[0] = '\0';
  5919        cat_id = ndpi_strtonum(dp->d_name, 1, NDPI_PROTOCOL_NUM_CATEGORIES - 1, &errstrp, 10);
  5920        if(errstrp == NULL) {
  5921          /* Valid file */
  5922          char path[512];
  5923
  5924          underscore[0] = '_';
  5925          snprintf(path, sizeof(path), "%s/%s", dir_path, dp->d_name);
  5926
  5927          if (ndpi_load_category_file(ndpi_str, path, (ndpi_protocol_category_t)cat_id) < 0) {
  5928            NDPI_LOG_ERR(ndpi_str, "Failed to load '%s'\n", path);
  5929            failed_files++;
  5930          }else
  5931            num_loaded++;
  5932        }
  5933      }
  5934    }
  5935
  5936    (void)closedir(dirp);
  5937
  5938    if(failed_files)
  5939      return(-1 * failed_files);
  5940
  5941    return(num_loaded);
  5942  }
